#!/bin/bash
# Prepara datos de prueba 3700 SOLO en el Docker local. Revertir con 99-revertir.sh
cd /c/Users/fvillacis/ClaudeLocalSession/sfa15
L="node qa-3700/qd.js LDCOM_DOS_PINOS_STAGING_DOCKER"; I="node qa-3700/qd.js ZZ_QA3700_INTEGRATIONS"
$L "IF NOT EXISTS (SELECT 1 FROM Parametro WHERE Emp_Id=1 AND Parametro_Nombre='Subdocumento_Tipo_Credito_Doc_Id') INSERT INTO Parametro (Emp_Id,Parametro_Nombre,Parametro_Valor,Parametro_Fec_Actualizacion) VALUES (1,'Subdocumento_Tipo_Credito_Doc_Id','4',GETDATE()); IF NOT EXISTS (SELECT 1 FROM Parametro WHERE Emp_Id=1 AND Parametro_Nombre='Subdocumento_Tipo_Credito_SubDoc_Id') INSERT INTO Parametro (Emp_Id,Parametro_Nombre,Parametro_Valor,Parametro_Fec_Actualizacion) VALUES (1,'Subdocumento_Tipo_Credito_SubDoc_Id','3',GETDATE()); UPDATE Plan_Financiamiento SET PlanFinanciamiento_Codigo_Externo='201' WHERE PlanFinanciamiento_Id=7 AND PlanFinanciamiento_Codigo_Externo='ZZ_TEST_LD10_007'; UPDATE Plan_Financiamiento SET PlanFinanciamiento_Codigo_Externo='203' WHERE PlanFinanciamiento_Id=3 AND PlanFinanciamiento_Codigo_Externo='ZZ_TEST_LD10_00299'; UPDATE Plan_Financiamiento SET PlanFinanciamiento_Codigo_Externo='204' WHERE PlanFinanciamiento_Id=5 AND PlanFinanciamiento_Codigo_Externo='ZZ_TEST_LD10_002'; UPDATE Plan_Financiamiento SET PlanFinanciamiento_Codigo_Externo='202' WHERE PlanFinanciamiento_Id=25 AND PlanFinanciamiento_Codigo_Externo='RGA10280237-J2'; UPDATE Cliente SET Cliente_Tiene_Financiamiento=1 WHERE Cliente_Id IN (4000010,4000054); SELECT Parametro_Nombre,Parametro_Valor FROM Parametro WHERE Parametro_Nombre LIKE 'Subdocumento_Tipo_Credito%'"
$I "IF NOT EXISTS (SELECT 1 FROM CrossReference WHERE CatalogId=1 AND ExternalId='001' AND InternalId='19' AND CompanyId=1) INSERT INTO CrossReference (CatalogId,ExternalId,InternalId,CompanyId) VALUES (1,'001','19',1); UPDATE IntegrationEvent SET IsActive=1, EndpointUrl='http://localhost:7391/active-bpel/rt/p_SFA15_Autorizacion_Venta_Final' WHERE Name='CREDIT_VALIDATION'; UPDATE IntegrationCredential SET AuthenticationUser='basic-usuario-prueba', AuthenticationPassword='basic-clave-prueba' WHERE EventCode='CREDIT_VALIDATION'; UPDATE P SET ParameterValue=CASE P.ParameterName WHEN 'SfaUser' THEN 'sim-sfa15' WHEN 'SfaPassword' THEN 'sim-sfa15-clave' WHEN 'CompanyCode' THEN '001' ELSE P.ParameterValue END FROM IntegrationEventParameter P JOIN IntegrationEvent E ON E.Id=P.IntegrationEventId WHERE E.Name='CREDIT_VALIDATION'; SELECT IsActive,EndpointUrl FROM IntegrationEvent WHERE Name='CREDIT_VALIDATION'"
